steps.starter:
// Lines that start with // are notes for people. The app skips them.
script "Arrive" for driving v1

// driving-standard sees nine lidar beams, its lane, its route, the light ahead,
// the car ahead, the nearest person in its path and its speed.
brain driving-standard

// This block runs for every SUV, 30 times per second of driving.
each tick {
  // Steer and press the pedal exactly as the brain says.
  drive(steer: brain.steer, pedal: brain.pedal)

  // A little for every meter of new ground along the route.
  reward +0.02 * route.gain
  // Add a prize for arriving here.
  // Leaving the road ends the trip, and costs half a point.
  reward -0.5 when car.offRoad

  // A brain that parks is going nowhere, so its trip ends after 8 seconds of that.
  stop "stuck" when car.noProgress > 8 s
}

